#include "interactions_source.h"
#include "preparation_authoring.hpp"
#include <iostream>
#include <fstream>
using namespace cyrus::interactions;
void require(bool x,const char* s){if(!x)throw std::runtime_error(s);}
template<class F>void rejects(F f){bool error=false;try{f();}catch(const std::exception&){error=true;}require(error,"Expected invalid authoring rejection");}
prep::Snapshot leaves(){prep::Snapshot s;for(float x:{-.02f,.02f,.04f}){unsigned b=unsigned(s.positions.size());for(unsigned k=0;k<5;++k){s.positions.push_back({x-.002f,0,k*.025f});s.positions.push_back({x+.002f,0,k*.025f});}for(unsigned k=0;k<4;++k){unsigned a=b+k*2;s.faces.push_back({a,a+1,a+2});s.faces.push_back({a+1,a+3,a+2});}}s.materials.assign(s.faces.size(),0);return s;}
int capturedPreparation(const char* filename){
    std::ifstream descriptor(filename);const auto file=Json::parse(descriptor);std::ifstream input(file.at("mesh").get<std::string>(),std::ios::binary);unsigned header[4]{};input.read(reinterpret_cast<char*>(header),sizeof(header));require(header[0]==0x53544c32u&&header[1]<=2000000&&header[2]<=4000000,"Captured source admission");
    prep::Snapshot mesh;mesh.positions.resize(header[1]);mesh.faces.resize(header[2]);mesh.materials.resize(header[2]);input.read(reinterpret_cast<char*>(mesh.positions.data()),mesh.positions.size()*12);input.read(reinterpret_cast<char*>(mesh.faces.data()),mesh.faces.size()*12);input.read(reinterpret_cast<char*>(mesh.materials.data()),mesh.materials.size()*4);require(bool(input),"Captured source payload");
    prep::Settings cfg;cfg.minimumLength=file.value("minimum_m",.05);cfg.connectionReach=file.value("connection_m",.001);cfg.foliageFraction=file.value("foliage_fraction",.05);std::atomic_bool cancel=false;const auto pieces=prep::inspectPieces(mesh,cfg,cancel);const auto selected=file.at("selected").get<std::vector<unsigned>>();auto intent=prep::selectedOnlyAuthoring(mesh,pieces,selected);const auto source=prepareSource(mesh,cfg,nullptr,&intent);
    require(source->rig->triangles==mesh.faces,"Captured scope retains all original triangles");require(source->rig->guides.size()==selected.size(),"Each selected leaf has one guide");
    if(file.contains("root_box"))for(const auto& guide:source->rig->guides){const auto p=guide.rest.nodes.front();const std::array<double,3> host{p.x,-p.z,p.y};for(unsigned axis=0;axis<3;++axis)require(host[axis]>=file["root_box"]["lo"][axis].get<double>()&&host[axis]<=file["root_box"]["hi"][axis].get<double>(),"Captured leaf root must remain at its crown rather than a drooping tip");}
    std::vector<bool> included(pieces.parts.size());for(auto id:selected)included[id]=true;for(unsigned id=0;id<included.size();++id)require(included[id]?source->rig->parts[id].stem:source->rig->parts[id].fixed,"Selected leaves bend; every other original piece remains fixed");
    auto saved=saveSource(*source);auto restored=prepareSource(mesh,cfg,&saved);require(restored->authoring==source->authoring,"Captured scope saved intent roundtrip");
    if(file.contains("save_source")){std::ofstream out(file.at("save_source").get<std::string>());out<<saved.dump();}
    std::cout<<Json{{"status","pass"},{"report",source->report},{"selected_pieces",selected.size()},{"source_vertices",mesh.positions.size()},{"source_triangles",mesh.faces.size()}}.dump(2)<<'\n';return 0;
}
int main(int argc,char** argv){try{if(argc==3&&std::string(argv[1])=="--fixture")return capturedPreparation(argv[2]);auto s=leaves();prep::Settings cfg;cfg.foliageFraction=1;std::atomic_bool cancel=false;auto pieces=prep::inspectPieces(s,cfg,cancel);require(pieces.parts.size()==3,"Stable complete component inspection");
    Json intent={{"version",1},{"fingerprint",prep::fingerprint(s)},{"parts",Json::array({{{"part",0},{"role",1}},{{"part",1},{"role",3}},{{"part",2},{"role",1}}})}};
    auto source=prepareSource(s,cfg,nullptr,&intent);require(source->rig->guides.size()==2,"Fixed piece must not generate a guide");require(source->rig->parts[1].fixed,"Fixed role applied");require(source->rig->triangles.size()==s.faces.size(),"Every source face retained");Pose rest;rest.guides.resize(2);rest.hiddenRoots.resize(2);for(unsigned i=0;i<s.positions.size();++i){auto p=posePoint(*source,rest,i);require(length(sub(p,{s.positions[i][0],s.positions[i][2],-s.positions[i][1]}))<1e-8,"Exact rest reproduction");}
    auto saved=saveSource(*source);require(saved["format"]==2,"Authored format guard");auto loaded=prepareSource(s,cfg,&saved);require(loaded->authoring==source->authoring,"Authored intent roundtrip");auto stale=s;stale.positions[0][0]+=.001f;rejects([&]{prepareSource(stale,cfg,nullptr,&intent);});
    auto scoped=prep::selectedOnlyAuthoring(s,pieces,{0,2});auto scopeSource=prepareSource(s,cfg,nullptr,&scoped);require(scopeSource->rig->guides.size()==2&&scopeSource->rig->parts[1].fixed,"Selected-only scope bends its leaves and retains other pieces fixed");
    require(scopeSource->rig->triangles==source->rig->triangles,"Selected scope retains every original triangle and corner");
    rejects([&]{prep::selectedOnlyAuthoring(s,pieces,{});});rejects([&]{prep::selectedOnlyAuthoring(s,pieces,{3});});rejects([&]{prep::selectedOnlyAuthoring(s,pieces,{0,0});});
    auto elevated=s;for(unsigned i=0;i<10;++i)elevated.positions[i][2]+=.5f;auto elevatedPieces=prep::inspectPieces(elevated,cfg,cancel);auto oneLeaf=prep::selectedOnlyAuthoring(elevated,elevatedPieces,{0});auto elevatedSource=prepareSource(elevated,cfg,nullptr,&oneLeaf);require(elevatedSource->rig->guides.size()==1&&elevatedSource->rig->parts[1].fixed&&elevatedSource->rig->parts[2].fixed,"One elevated leaf can be rooted with all trunk/detail pieces fixed");
    auto scopedSaved=saveSource(*elevatedSource);auto scopedReloaded=prepareSource(elevated,cfg,&scopedSaved);require(scopedReloaded->authoring==elevatedSource->authoring,"Selected-only scope roundtrips without a new format");
    auto follow=intent;follow["parts"][1]={{"part",1},{"role",2},{"parent",0}};auto attached=prepareSource(s,cfg,nullptr,&follow);require(!attached->rig->parts[1].stem&&!attached->rig->parts[1].fixed,"Follow role is rigid attachment");require(attached->rig->parts[1].guide==attached->rig->parts[0].guide,"Follow exact parent");
    auto cyclic=intent;cyclic["parts"][0]["parent"]=2;cyclic["parts"][2]["parent"]=0;rejects([&]{prepareSource(s,cfg,nullptr,&cyclic);});
    auto duplicate=intent;duplicate["parts"].push_back(duplicate["parts"][0]);rejects([&]{prepareSource(s,cfg,nullptr,&duplicate);});
    auto invalidRoot=intent;invalidRoot["parts"][0]["root_vertex"]=15;rejects([&]{prepareSource(s,cfg,nullptr,&invalidRoot);});
    auto allFixed=intent;for(auto& r:allFixed["parts"])r["role"]=3;rejects([&]{prepareSource(s,cfg,nullptr,&allFixed);});
    auto moved=intent;moved["parts"][0]["nodes"]=Json::array({Json::array({-.02,0,0}),Json::array({-.01,0,.05}),Json::array({-.02,0,.1})});auto custom=prepareSource(s,cfg,nullptr,&moved);require(custom->rig->guides[0].rest.nodes.size()==3,"Manual guide nodes");
    cancel=true;rejects([&]{prep::inspectPieces(s,cfg,cancel);});std::cout<<"PASS source roles, complete geometry, exact rest, authored persistence, parents, cycles, roots and cancellation\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
